commands:
cd <WORKSPACE>/pantry
pwsh -NoLogo -NoProfile -Command '
Import-Module PSScriptAnalyzer -ErrorAction Stop
foreach ($f in @("./podex.ps1","./api/_lib/pantry-store.ps1")) {
	$r = Invoke-ScriptAnalyzer -Path $f -Severity Error,Warning
	Write-Host "=== $f ==="
	if (-not $r) { Write-Host "  clean (no Error/Warning)" }
	else { $r | ForEach-Object { Write-Host ("  [{0}] {1} L{2}: {3}" -f $_.Severity,$_.RuleName,$_.Line,$_.Message) } }
}
' 2>&1 | head -40
